package com.example.ragnarokdatabase.data.remote

import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.Monster
import com.example.ragnarokdatabase.model.PopularItemsResponse
import retrofit2.http.GET
import retrofit2.http.Path
import retrofit2.http.Query

/**
 * Declaration of the endpoints we use from the Ragnarok API.
 * Retrofit generates the concrete implementation based on this interface.
 */
interface RagnarokApiService {

    /**
     * Retrieves the details of an item by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("items/{id}")
    suspend fun getItem(@Path("id") itemId: Int): Item

    /**
     * Retrieves the details of a monster by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("monsters/{id}")
    suspend fun getMonster(@Path("id") monsterId: Int): Monster

    /**
     * Gets popular items according to the specified time period.
     * period can be: today, yesterday, last7days, last30days
     * limit controls how many items the response brings (default 10)
     */
    @GET("items/popular/{period}")
    suspend fun getPopularItems(
        @Path("period") period: String,
        @Query("limit") limit: Int = 10
    ): PopularItemsResponse
}

package com.example.ragnarokdatabase.data.remote

import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.Monster
import com.example.ragnarokdatabase.model.PopularItemsResponse
import retrofit2.http.GET
import retrofit2.http.Path
import retrofit2.http.Query

/**
 * Declaration of the endpoints we use from the Ragnarok API.
 * Retrofit generates the concrete implementation based on this interface.
 */
interface RagnarokApiService {

    /**
     * Retrieves the details of an item by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("items/{id}")
    suspend fun getItem(@Path("id") itemId: Int): Item

    /**
     * Retrieves the details of a monster by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("monsters/{id}")
    suspend fun getMonster(@Path("id") monsterId: Int): Monster

    /**
     * Gets popular items according to the specified time period.
     * period can be: today, yesterday, last7days, last30days
     * limit controls how many items the response brings (default 10)
     */
    @GET("items/popular/{period}")
    suspend fun getPopularItems(
        @Path("period") period: String,
        @Query("limit") limit: Int = 10
    ): PopularItemsResponse

    /**
     * Universal search for items.
     * If query is a number → searches by ID
     * If query is text → partial search by name (case-insensitive)
     * limit controls how many items the response brings (default 50, max 500)
     */
    @GET("items/search")
    suspend fun searchItems(
        @Query("query") query: String,
        @Query("limit") limit: Int = 50
    ): List<Item>
}

package com.example.ragnarokdatabase.data.repository

import com.example.ragnarokdatabase.data.remote.NetworkModule
import com.example.ragnarokdatabase.data.remote.RagnarokApiService
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.PopularItem

/**
 * Encapsulates network access so that the rest of the layers don't know
 * whether the data comes from the web, cache, or a local database.
 * This is where we could combine multiple sources without changing the UI.
 */
class ItemRepository(
    private val api: RagnarokApiService = NetworkModule.api
) {
    /**
     * Queries the details of an item by its ID.
     */
    suspend fun getItem(itemId: Int): Item {
        return api.getItem(itemId)
    }

    /**
     * Gets popular items according to the time period.
     * period can be: today, yesterday, last7days, last30days
     */
    suspend fun getPopularItems(period: String, limit: Int = 10): List<PopularItem> {
        return api.getPopularItems(period, limit).items
    }
}

package com.example.ragnarokdatabase.data.repository

import com.example.ragnarokdatabase.data.remote.NetworkModule
import com.example.ragnarokdatabase.data.remote.RagnarokApiService
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.PopularItem

/**
 * Encapsulates network access so that the rest of the layers don't know
 * whether the data comes from the web, cache, or a local database.
 * This is where we could combine multiple sources without changing the UI.
 */
class ItemRepository(
    private val api: RagnarokApiService = NetworkModule.api
) {
    /**
     * Queries the details of an item by its ID.
     */
    suspend fun getItem(itemId: Int): Item {
        return api.getItem(itemId)
    }

    /**
     * Gets popular items according to the time period.
     * period can be: today, yesterday, last7days, last30days
     */
    suspend fun getPopularItems(period: String, limit: Int = 10): List<PopularItem> {
        return api.getPopularItems(period, limit).items
    }

    /**
     * Searches for items by query (ID or name).
     * If query is a number, searches by ID.
     * If query is text, performs partial search by name.
     */
    suspend fun searchItems(query: String, limit: Int = 50): List<Item> {
        return api.searchItems(query, limit)
    }
}

package com.example.ragnarokdatabase.navigation

import androidx.compose.animation.AnimatedContentTransitionScope
import androidx.compose.animation.core.tween
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavHostController
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.navArgument
import com.example.ragnarokdatabase.view.ItemDetailScreen
import com.example.ragnarokdatabase.view.MainScreen
import com.example.ragnarokdatabase.viewmodel.MainViewModel

/**
 * Definition of the application's navigation routes
 */
sealed class Screen(val route: String) {
    object Main : Screen("main")
    object ItemDetail : Screen("item/{itemId}") {
        fun createRoute(itemId: Int) = "item/$itemId"
    }
}

/**
 * Application's NavHost that defines all navigation
 */
@Composable
fun RagnarokNavHost(
    navController: NavHostController
) {
    // Share the MainScreen ViewModel between recompositions
    val mainViewModel: MainViewModel = viewModel()

    NavHost(
        navController = navController,
        startDestination = Screen.Main.route
    ) {
        composable(
            route = Screen.Main.route,
            enterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            },
            exitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            popEnterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            },
            popExitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            }
        ) { backStackEntry ->
            // Detect when navigating back to this screen
            LaunchedEffect(backStackEntry) {
                // Reload items with the currently selected period
                mainViewModel.refreshCurrentPeriod()
            }

            MainScreen(
                onItemClick = { itemId ->
                    navController.navigate(Screen.ItemDetail.createRoute(itemId))
                },
                viewModel = mainViewModel
            )
        }

        composable(
            route = Screen.ItemDetail.route,
            arguments = listOf(
                navArgument("itemId") {
                    type = NavType.IntType
                }
            ),
            enterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            exitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            popEnterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            },
            popExitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            }
        ) { backStackEntry ->
            val itemId = backStackEntry.arguments?.getInt("itemId") ?: 0
            ItemDetailScreen(
                itemId = itemId,
                onNavigateBack = {
                    navController.popBackStack()
                }
            )
        }
    }
}

package com.example.ragnarokdatabase.navigation

import androidx.compose.animation.AnimatedContentTransitionScope
import androidx.compose.animation.core.tween
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavHostController
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.navArgument
import com.example.ragnarokdatabase.view.ItemDetailScreen
import com.example.ragnarokdatabase.view.MainScreen
import com.example.ragnarokdatabase.view.SearchScreen
import com.example.ragnarokdatabase.viewmodel.MainViewModel

/**
 * Definition of the application's navigation routes
 */
sealed class Screen(val route: String) {
    object Main : Screen("main")
    object Search : Screen("search?query={query}") {
        fun createRoute(query: String = "") = "search?query=$query"
    }
    object ItemDetail : Screen("item/{itemId}") {
        fun createRoute(itemId: Int) = "item/$itemId"
    }
}

/**
 * Application's NavHost that defines all navigation
 */
@Composable
fun RagnarokNavHost(
    navController: NavHostController
) {
    // Share the MainScreen ViewModel between recompositions
    val mainViewModel: MainViewModel = viewModel()

    NavHost(
        navController = navController,
        startDestination = Screen.Main.route
    ) {
        composable(
            route = Screen.Main.route,
            enterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            },
            exitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            popEnterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            },
            popExitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            }
        ) { backStackEntry ->
            // Detect when navigating back to this screen
            LaunchedEffect(backStackEntry) {
                // Reload items with the currently selected period
                mainViewModel.refreshCurrentPeriod()
            }

            MainScreen(
                onItemClick = { itemId ->
                    navController.navigate(Screen.ItemDetail.createRoute(itemId))
                },
                onSearchClick = { query ->
                    navController.navigate(Screen.Search.createRoute(query))
                },
                viewModel = mainViewModel
            )
        }

        composable(
            route = Screen.Search.route,
            arguments = listOf(
                navArgument("query") {
                    type = NavType.StringType
                    defaultValue = ""
                    nullable = true
                }
            ),
            enterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            exitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            popEnterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            },
            popExitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            }
        ) { backStackEntry ->
            val initialQuery = backStackEntry.arguments?.getString("query") ?: ""
            SearchScreen(
                initialQuery = initialQuery,
                onNavigateBack = {
                    navController.popBackStack()
                },
                onItemClick = { itemId ->
                    navController.navigate(Screen.ItemDetail.createRoute(itemId))
                }
            )
        }

        composable(
            route = Screen.ItemDetail.route,
            arguments = listOf(
                navArgument("itemId") {
                    type = NavType.IntType
                }
            ),
            enterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            exitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(300)
                )
            },
            popEnterTransition = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            },
            popExitTransition = {
                slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(300)
                )
            }
        ) { backStackEntry ->
            val itemId = backStackEntry.arguments?.getInt("itemId") ?: 0
            ItemDetailScreen(
                itemId = itemId,
                onNavigateBack = {
                    navController.popBackStack()
                }
            )
        }
    }
}

package com.example.ragnarokdatabase.view

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.lifecycle.viewmodel.compose.viewModel
import coil.compose.AsyncImage
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.ui.theme.*
import com.example.ragnarokdatabase.viewmodel.ItemDetailUiState
import com.example.ragnarokdatabase.viewmodel.ItemDetailViewModel

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ItemDetailScreen(
    itemId: Int,
    onNavigateBack: () -> Unit,
    viewModel: ItemDetailViewModel = viewModel()
) {
    val uiState by viewModel.uiState.collectAsState()

    LaunchedEffect(itemId) {
        viewModel.loadItemDetail(itemId)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        Slate900,
                        Slate950
                    )
                )
            )
    ) {
        when (val state = uiState) {
            is ItemDetailUiState.Loading -> {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    CircularProgressIndicator(color = Amber400)
                }
            }
            is ItemDetailUiState.Success -> {
                ItemDetailContent(
                    item = state.item,
                    onNavigateBack = onNavigateBack
                )
            }
            is ItemDetailUiState.Error -> {
                ErrorContent(
                    message = state.message,
                    onNavigateBack = onNavigateBack
                )
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ItemDetailContent(
    item: Item,
    onNavigateBack: () -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
    ) {
        // Top App Bar
        TopAppBar(
            title = { },
            navigationIcon = {
                IconButton(onClick = onNavigateBack) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                        contentDescription = "Back",
                        tint = Slate200
                    )
                }
            },
            colors = TopAppBarDefaults.topAppBarColors(
                containerColor = Slate900.copy(alpha = 0.95f)
            )
        )

        // Item Image
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(300.dp)
                .background(Slate800),
            contentAlignment = Alignment.Center
        ) {
            AsyncImage(
                model = item.getCollectionImageUrl(),
                contentDescription = item.name,
                modifier = Modifier
                    .size(200.dp)
                    .clip(RoundedCornerShape(16.dp)),
                contentScale = ContentScale.Fit
            )
        }

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(24.dp)
        ) {
            // Item Name
            Text(
                text = item.name,
                style = MaterialTheme.typography.headlineLarge.copy(
                    fontFamily = LilitaOneFont
                ),
                color = Amber400,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(8.dp))

            // Item Type
            Text(
                text = item.type + (item.subtype?.let { " - $it" } ?: ""),
                style = MaterialTheme.typography.titleMedium,
                color = Slate400,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(32.dp))

            // Description
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Slate800
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp)
                ) {
                    Text(
                        text = "DESCRIPTION",
                        style = MaterialTheme.typography.titleSmall.copy(
                            fontFamily = LilitaOneFont
                        ),
                        color = Amber400
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = item.description,
                        style = MaterialTheme.typography.bodyMedium,
                        color = Slate200
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Price Info
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                PriceCard(
                    title = "BUY PRICE",
                    price = item.buyPrice,
                    modifier = Modifier.weight(1f)
                )
                PriceCard(
                    title = "SELL PRICE",
                    price = item.sellPrice,
                    modifier = Modifier.weight(1f)
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Stats Card
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Slate800
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp)
                ) {
                    Text(
                        text = "STATS",
                        style = MaterialTheme.typography.titleSmall.copy(
                            fontFamily = LilitaOneFont
                        ),
                        color = Amber400
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    item.stats.atk?.let {
                        StatRow(label = "Attack", value = it.toString())
                    }
                    item.stats.matk?.let {
                        StatRow(label = "Magic Attack", value = it.toString())
                    }
                    item.stats.defense?.let {
                        StatRow(label = "Defense", value = it.toString())
                    }
                    StatRow(label = "Weight", value = (item.stats.weight / 10).toString())
                    StatRow(label = "Slots", value = item.stats.slots.toString())
                }
            }

            // Requirements Card - Only show if there are meaningful requirements
            if (item.requiredLevel > 1 || item.requiredJob != null || item.gender != null || item.location != null) {
                Spacer(modifier = Modifier.height(16.dp))

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Slate800
                    )
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "REQUIREMENTS",
                            style = MaterialTheme.typography.titleSmall.copy(
                                fontFamily = LilitaOneFont
                            ),
                            color = Amber400
                        )
                        Spacer(modifier = Modifier.height(12.dp))

                        if (item.requiredLevel > 1) {
                            RequirementRow(label = "Level", value = item.requiredLevel.toString())
                        }
                        item.getRequiredJobsText()?.let {
                            RequirementRow(label = "Job", value = it)
                        }
                        item.gender?.let {
                            RequirementRow(label = "Gender", value = it)
                        }
                        item.location?.let {
                            RequirementRow(label = "Location", value = it)
                        }
                    }
                }
            }

            // Script Card - Show if any script exists
            if (item.script != null || item.equipScript != null || item.unequipScript != null) {
                Spacer(modifier = Modifier.height(16.dp))

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Slate800
                    )
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "SCRIPT",
                            style = MaterialTheme.typography.titleSmall.copy(
                                fontFamily = LilitaOneFont
                            ),
                            color = Amber400
                        )
                        Spacer(modifier = Modifier.height(12.dp))

                        item.script?.let { script ->
                            Text(
                                text = script,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }

                        item.equipScript?.let { equipScript ->
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "On Equip:",
                                style = MaterialTheme.typography.labelMedium,
                                color = Amber400
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = equipScript,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }

                        item.unequipScript?.let { unequipScript ->
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "On Unequip:",
                                style = MaterialTheme.typography.labelMedium,
                                color = Amber400
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = unequipScript,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(40.dp))
        }
    }
}

@Composable
fun PriceCard(
    title: String,
    price: Int,
    modifier: Modifier = Modifier
) {
    Card(
        modifier = modifier,
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = Slate800
        )
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = title,
                style = MaterialTheme.typography.labelSmall.copy(
                    fontFamily = LilitaOneFont
                ),
                color = Slate400
            )
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = "${price}z",
                style = MaterialTheme.typography.titleLarge.copy(
                    fontWeight = FontWeight.Bold
                ),
                color = Amber400
            )
        }
    }
}

@Composable
fun StatRow(label: String, value: String) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Text(
            text = label,
            style = MaterialTheme.typography.bodyMedium,
            color = Slate300
        )
        Text(
            text = value,
            style = MaterialTheme.typography.bodyMedium.copy(
                fontWeight = FontWeight.Bold
            ),
            color = Slate100
        )
    }
}

@Composable
fun RequirementRow(label: String, value: String) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Text(
            text = label,
            style = MaterialTheme.typography.bodyMedium,
            color = Slate300
        )
        Text(
            text = value,
            style = MaterialTheme.typography.bodyMedium.copy(
                fontWeight = FontWeight.Bold
            ),
            color = Amber400
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ErrorContent(
    message: String,
    onNavigateBack: () -> Unit
) {
    Column(
        modifier = Modifier.fillMaxSize()
    ) {
        TopAppBar(
