import com.example.ragnarokdatabase.viewmodel.MainUiState
import com.example.ragnarokdatabase.viewmodel.MainViewModel

val LilitaOneFont = FontFamily(Font(R.font.lilitaone_regular))

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MainScreen(
    viewModel: MainViewModel = viewModel()
) {
    val uiState by viewModel.uiState.collectAsState()
    val selectedPeriod by viewModel.selectedPeriod.collectAsState()
    var searchQuery by remember { mutableStateOf("") }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        Slate900,
                        Slate950
                    )
                )
            )
    ) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 24.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            item {
                Spacer(modifier = Modifier.height(60.dp))

                // Header
                Text(
                    text = "RAGNAROK",
                    style = MaterialTheme.typography.displayMedium.copy(
                        fontFamily = LilitaOneFont
                    ),
                    color = Amber400,
                    textAlign = TextAlign.Center
                )

                Text(
                    text = "DATABASE",
                    style = MaterialTheme.typography.headlineLarge.copy(
                        fontFamily = LilitaOneFont
                    ),
                    color = Slate200,
                    textAlign = TextAlign.Center
                )

                Spacer(modifier = Modifier.height(48.dp))

                // Search Bar
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp),
                    placeholder = {
                        Text(
                            text = "Search items, monsters...",
                            color = Slate500
                        )
                    },
                    leadingIcon = {
                        Icon(
                            imageVector = Icons.Default.Search,
                            contentDescription = "Search",
                            tint = Amber400
                        )
                    },
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = Slate100,
                        unfocusedTextColor = Slate200,
                        focusedBorderColor = Amber400,
                        unfocusedBorderColor = Slate600,
                        cursorColor = Amber400
                    ),
                    shape = RoundedCornerShape(16.dp)
                )

                Spacer(modifier = Modifier.height(40.dp))

                // Popular Items Section
                Text(
                    text = "POPULAR ITEMS",
                    style = MaterialTheme.typography.titleLarge.copy(
                        fontFamily = LilitaOneFont
                    ),
                    color = Slate200,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Start
                )

                Spacer(modifier = Modifier.height(16.dp))

                // Period Filter Chips
                PeriodFilterChips(
                    selectedPeriod = selectedPeriod,
                    onPeriodSelected = { viewModel.loadPopularItems(it) }
                )

                Spacer(modifier = Modifier.height(24.dp))
            }

            // Popular Items List
            when (val state = uiState) {
                is MainUiState.Loading -> {
                    item {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(400.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            CircularProgressIndicator(
                                color = Amber400
                            )
                        }
                    }
                }
                is MainUiState.Success -> {
                    items(state.items) { item ->
                        PopularItemCard(item = item)
                        Spacer(modifier = Modifier.height(12.dp))
                    }
                }
                is MainUiState.Error -> {
                    item {
                        ErrorCard(message = state.message)
                    }
                }
            }

            item {
                Spacer(modifier = Modifier.height(40.dp))
            }
        }
    }
}

@Composable
fun PeriodFilterChips(
    selectedPeriod: String,
    onPeriodSelected: (String) -> Unit
) {
    val periods = listOf(
        "today" to "Today",
        "yesterday" to "Yesterday",
        "last7days" to "Last 7 Days",
        "last30days" to "Last 30 Days"
    )

    LazyRow(
        horizontalArrangement = Arrangement.spacedBy(12.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        items(
            count = periods.size,
            key = { index -> periods[index].first }
        ) { index ->
            val (key, label) = periods[index]
            FilterChip(
                selected = selectedPeriod == key,
                onClick = { onPeriodSelected(key) },
                label = {
                    Text(
                        text = label,
                        style = MaterialTheme.typography.labelLarge
                    )
                },
                colors = FilterChipDefaults.filterChipColors(
                    selectedContainerColor = Amber400,
                    selectedLabelColor = Slate950,
                    containerColor = Slate800,
                    labelColor = Slate300
                ),
                border = FilterChipDefaults.filterChipBorder(
                    enabled = true,
                    selected = selectedPeriod == key,
                    selectedBorderColor = Amber400,
                    borderColor = Slate600,
                    borderWidth = 1.dp
                )
            )
        }
    }
}

@Composable
fun PopularItemCard(item: PopularItem) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .height(80.dp)
            .clickable { /* TODO: Navigate to item detail */ },
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = Slate800
        ),
        elevation = CardDefaults.cardElevation(
            defaultElevation = 2.dp
        )
    ) {
        Row(
            modifier = Modifier
                .fillMaxSize()
                .padding(12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Item Icon
            AsyncImage(
                model = item.getIconUrl(),
                contentDescription = item.name,
                modifier = Modifier
                    .size(56.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(Slate700),
                contentScale = ContentScale.Fit
            )

            Spacer(modifier = Modifier.width(16.dp))

            // Item Info
            Column(
                modifier = Modifier.weight(1f)
            ) {
                Text(
                    text = item.name,
                    style = MaterialTheme.typography.titleMedium,
                    color = Slate100,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                Spacer(modifier = Modifier.height(4.dp))

                Text(
                    text = item.type,
                    style = MaterialTheme.typography.bodySmall,
                    color = Slate400
                )
            }

            // View Count Badge
            Surface(
                shape = CircleShape,
                color = Amber400.copy(alpha = 0.2f)
            ) {
                Text(
                    text = "${item.viewCount} views",
                    style = MaterialTheme.typography.labelSmall,
                    color = Amber400,
                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp)
                )
            }
        }
    }
}

@Composable
fun ErrorCard(message: String) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = Red900.copy(alpha = 0.3f)
        )
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = "Error",
                style = MaterialTheme.typography.titleLarge.copy(
                    fontFamily = LilitaOneFont
                ),
                color = Red400
            )

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = message,
                style = MaterialTheme.typography.bodyMedium,
                color = Slate300,
                textAlign = TextAlign.Center
            )
        }
    }
}

