                text = "The item you're looking for doesn't exist",
                style = MaterialTheme.typography.bodyMedium,
                color = Slate500,
                textAlign = TextAlign.Center
            )
        }
    }
}

@Composable
fun SearchResultsList(
    items: List<Item>,
    onItemClick: (Int) -> Unit
) {
    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 24.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        item {
            Text(
                text = "${items.size} result${if (items.size != 1) "s" else ""} found",
                style = MaterialTheme.typography.labelLarge,
                color = Slate400,
                modifier = Modifier.padding(bottom = 8.dp)
            )
        }

        items(items) { item ->
            SearchResultCard(
                item = item,
                onItemClick = { onItemClick(item.id) }
            )
        }

        item {
            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

@Composable
fun SearchResultCard(
    item: Item,
    onItemClick: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onItemClick() },
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = Slate800
        ),
        elevation = CardDefaults.cardElevation(
            defaultElevation = 2.dp
        )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Item Icon
            AsyncImage(
                model = item.getIconUrl(),
                contentDescription = item.name,
                modifier = Modifier
                    .size(56.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(Slate700),
                contentScale = ContentScale.Fit
            )

            Spacer(modifier = Modifier.width(16.dp))

            // Item Info
            Column(
                modifier = Modifier.weight(1f)
            ) {
                Text(
                    text = item.name,
                    style = MaterialTheme.typography.titleMedium,
                    color = Slate100,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                Spacer(modifier = Modifier.height(4.dp))

                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = item.type,
                        style = MaterialTheme.typography.bodySmall,
                        color = Slate400
                    )
                    item.subtype?.let { subtype ->
                        Text(
                            text = "•",
                            style = MaterialTheme.typography.bodySmall,
                            color = Slate600
                        )
                        Text(
                            text = subtype,
                            style = MaterialTheme.typography.bodySmall,
                            color = Slate400
                        )
                    }
                }

                Spacer(modifier = Modifier.height(4.dp))

                Text(
                    text = "ID: ${item.id}",
                    style = MaterialTheme.typography.labelSmall,
                    color = Slate500
                )
            }
        }
    }
}

package com.example.ragnarokdatabase.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.Item
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * ViewModel for the item detail screen.
 * Manages the loading and state of the detailed item information.
 */
class ItemDetailViewModel(
    private val itemRepository: ItemRepository = ItemRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<ItemDetailUiState>(ItemDetailUiState.Loading)
    val uiState: StateFlow<ItemDetailUiState> = _uiState.asStateFlow()

    fun loadItemDetail(itemId: Int) {
        viewModelScope.launch {
            _uiState.value = ItemDetailUiState.Loading
            try {
                val item = itemRepository.getItem(itemId)
                _uiState.value = ItemDetailUiState.Success(item)
            } catch (e: Exception) {
                _uiState.value = ItemDetailUiState.Error(e.message ?: "Unknown error")
            }
        }
    }
}

/**
 * Possible states of the detail screen
 */
sealed class ItemDetailUiState {
    object Loading : ItemDetailUiState()
    data class Success(val item: Item) : ItemDetailUiState()
    data class Error(val message: String) : ItemDetailUiState()
}

package com.example.ragnarokdatabase.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.Item
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * ViewModel for the item detail screen.
 * Manages the loading and state of the detailed item information.
 */
class ItemDetailViewModel(
    private val itemRepository: ItemRepository = ItemRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<ItemDetailUiState>(ItemDetailUiState.Loading)
    val uiState: StateFlow<ItemDetailUiState> = _uiState.asStateFlow()

    fun loadItemDetail(itemId: Int) {
        viewModelScope.launch {
            _uiState.value = ItemDetailUiState.Loading
            try {
                val item = itemRepository.getItem(itemId)
                _uiState.value = ItemDetailUiState.Success(item)
            } catch (e: Exception) {
                _uiState.value = when {
                    e.message?.contains("404") == true -> ItemDetailUiState.NotFound
                    e.message?.contains("HTTP") == true -> ItemDetailUiState.Error("Network error. Please try again.")
                    else -> ItemDetailUiState.Error(e.message ?: "Unknown error")
                }
            }
        }
    }
}

/**
 * Possible states of the detail screen
 */
sealed class ItemDetailUiState {
    object Loading : ItemDetailUiState()
    object NotFound : ItemDetailUiState()
    data class Success(val item: Item) : ItemDetailUiState()
    data class Error(val message: String) : ItemDetailUiState()
}

package com.example.ragnarokdatabase.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.PopularItem
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * ViewModel for the main screen.
 * Manages the state of popular items according to different time periods.
 */
class MainViewModel(
    private val itemRepository: ItemRepository = ItemRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<MainUiState>(MainUiState.Loading)
    val uiState: StateFlow<MainUiState> = _uiState.asStateFlow()

    private val _selectedPeriod = MutableStateFlow("today")
    val selectedPeriod: StateFlow<String> = _selectedPeriod.asStateFlow()

    init {
        loadPopularItems("today")
    }

    fun loadPopularItems(period: String) {
        viewModelScope.launch {
            _uiState.value = MainUiState.Loading
            _selectedPeriod.value = period
            try {
                val items = itemRepository.getPopularItems(period, limit = 10)
                _uiState.value = MainUiState.Success(items)
            } catch (e: Exception) {
                _uiState.value = MainUiState.Error(e.message ?: "Unknown error")
            }
        }
    }

    /**
     * Reloads popular items with the currently selected period.
     * Useful for refreshing the list after navigating back.
     */
    fun refreshCurrentPeriod() {
        loadPopularItems(_selectedPeriod.value)
    }
}

/**
 * Possible states of the main screen
 */
sealed class MainUiState {
    object Loading : MainUiState()
    data class Success(val items: List<PopularItem>) : MainUiState()
    data class Error(val message: String) : MainUiState()
}

package com.example.ragnarokdatabase.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.PopularItem
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * ViewModel for the main screen.
 * Manages the state of popular items according to different time periods.
 */
class MainViewModel(
    private val itemRepository: ItemRepository = ItemRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<MainUiState>(MainUiState.Loading)
    val uiState: StateFlow<MainUiState> = _uiState.asStateFlow()

    private val _selectedPeriod = MutableStateFlow("today")
    val selectedPeriod: StateFlow<String> = _selectedPeriod.asStateFlow()

    init {
        loadPopularItems("today")
    }

    fun loadPopularItems(period: String) {
        viewModelScope.launch {
            _uiState.value = MainUiState.Loading
            _selectedPeriod.value = period
            try {
                val items = itemRepository.getPopularItems(period, limit = 10)
                _uiState.value = MainUiState.Success(items)
            } catch (e: Exception) {
                val errorMessage = when {
                    e.message?.contains("404") == true -> "Popular items not found"
                    e.message?.contains("HTTP") == true -> "Network error. Please try again."
                    else -> e.message ?: "Unknown error"
                }
                _uiState.value = MainUiState.Error(errorMessage)
            }
        }
    }

    /**
     * Reloads popular items with the currently selected period.
     * Useful for refreshing the list after navigating back.
     */
    fun refreshCurrentPeriod() {
        loadPopularItems(_selectedPeriod.value)
    }
}

/**
 * Possible states of the main screen
 */
sealed class MainUiState {
    object Loading : MainUiState()
    data class Success(val items: List<PopularItem>) : MainUiState()
    data class Error(val message: String) : MainUiState()
}

package com.example.ragnarokdatabase.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.Item
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * ViewModel for the search screen.
 * Manages the search state and performs item searches with debouncing.
 */
class SearchViewModel(
    private val itemRepository: ItemRepository = ItemRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<SearchUiState>(SearchUiState.Idle)
    val uiState: StateFlow<SearchUiState> = _uiState.asStateFlow()

    private val _searchQuery = MutableStateFlow("")
    val searchQuery: StateFlow<String> = _searchQuery.asStateFlow()

    private var searchJob: Job? = null

    /**
     * Updates the search query and triggers a search after a debounce delay
     */
    fun onSearchQueryChanged(query: String) {
        _searchQuery.value = query

        // Cancel previous search job
        searchJob?.cancel()

        if (query.isBlank()) {
            _uiState.value = SearchUiState.Idle
            return
        }

        // Debounce search - wait 500ms after user stops typing
        searchJob = viewModelScope.launch {
            delay(500)
            searchItems(query)
        }
    }

    /**
     * Performs immediate search without debouncing
     */
    fun searchNow(query: String) {
        _searchQuery.value = query
        searchJob?.cancel()

        if (query.isBlank()) {
            _uiState.value = SearchUiState.Idle
            return
        }

        searchItems(query)
    }

    private fun searchItems(query: String) {
        viewModelScope.launch {
            _uiState.value = SearchUiState.Loading
            try {
                val results = itemRepository.searchItems(query, limit = 50)
                _uiState.value = if (results.isEmpty()) {
                    SearchUiState.Empty
                } else {
                    SearchUiState.Success(results)
                }
            } catch (e: Exception) {
                _uiState.value = when {
                    e.message?.contains("404") == true -> SearchUiState.NotFound
                    e.message?.contains("HTTP") == true -> SearchUiState.Error("Network error. Please try again.")
                    else -> SearchUiState.Error(e.message ?: "Unknown error")
                }
            }
        }
    }

    /**
     * Clears the search and resets to idle state
     */
    fun clearSearch() {
        searchJob?.cancel()
        _searchQuery.value = ""
        _uiState.value = SearchUiState.Idle
    }
}

/**
 * Possible states of the search screen
 */
sealed class SearchUiState {
    object Idle : SearchUiState()
    object Loading : SearchUiState()
    object Empty : SearchUiState()
    object NotFound : SearchUiState()
    data class Success(val items: List<Item>) : SearchUiState()
    data class Error(val message: String) : SearchUiState()
}

